 @Test public void inputBoundaryRecoveryRetainsRngExposureAndChampion(){EvolutionLoopR27.Config cfg=new EvolutionLoopR27.Config();cfg.nullControl=false;FeatureCacheR27 cache=RepairObservatoryR30Test.ctx().cache;EvolutionLoopR27 loop=new EvolutionLoopR27(cfg,cache,new R27BirthGateTest.Recorder(),()->0);loop.step=5;loop.generation=9;loop.rng.state=991;loop.champion=RepairObservatoryR30Test.parent();loop.ledger().restore(12,loop.champion.policyHash());FeatureCacheR27 newCache=new FeatureCacheR27(cache.data.planted(.4,76));EvolutionLoopR27 recovered=RepairCompatibilityR30R1.restoreBoundary(loop.snapshot(),cfg,newCache,new R27BirthGateTest.Recorder(),()->0);assertEquals(1,recovered.step);assertEquals(10,recovered.generation);assertEquals(991,recovered.rng.state);assertEquals(loop.champion.policyHash(),recovered.champion.policyHash());assertTrue(recovered.ledger().seen(12,loop.champion.policyHash()));assertEquals("MAIN_REPAIR1",RuntimeR27.LOOP);}
 @Test public void newHardSetsHaveAnIsolatedLiveParserNamespace(){PolicySpecR27 p=SetIntersectionPolicyR30.conditional(1,32,128,IdeaFamilyR27.meta("I20","TEST",0,1,"HOST"));assertEquals("ACTIVE_REPAIR1",RepairCompatibilityR30R1.activeStatus(p));assertTrue(RepairCompatibilityR30R1.active("ACTIVE_REPAIR1"));assertFalse(LiveShadowsR27.LIVE_STATES.isEmpty());assertTrue(PolicyContractR30.violations(p).toString(),PolicyContractR30.violations(p).isEmpty());assertEquals(p.policyHash(),PolicySpecR27.parse(p.fullJson()).policyHash());assertTrue(Double.isNaN(PolicyAstR27.eval(p.ast,RepairObservatoryR30Test.ctx().cache,p.position)[0]));}
